<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue';import MPopover from '../MPopover.vue';import MValueBridge from './MValueBridge.vue';import {treeEntries,pathKey,descendants,moveInList} from './tree';import type {MTreeEntry} from './tree';import type {MCascaderProps,MReferenceTreeOption} from './types';import {useReferenceConfig} from './locale';
const props=withDefaults(defineProps<MCascaderProps>(),{filterable:true,multiple:false,checkStrictly:false,checkedPaths:()=>[]});const emit=defineEmits<{ 'update:modelValue':[value:string[]];'update:checkedPaths':[paths:string[][]] }>();const {t}=useReferenceConfig();const open=ref(false),query=ref(''),active=ref<string[]>([...props.modelValue]);const all=computed(()=>treeEntries(props.options));
const columns=computed(()=>{const groups:{nodes:readonly MReferenceTreeOption[];prefix:string[]}[]=[{nodes:props.options,prefix:[]}];let nodes=props.options;for(let level=0;level<active.value.length;level++){const item=nodes.find(node=>node.value===active.value[level]);if(!item?.children?.length)break;groups.push({nodes:item.children,prefix:active.value.slice(0,level+1)});nodes=item.children;}return groups;});
const selectedPaths=computed(()=>props.multiple?props.checkedPaths:props.modelValue.length?[props.modelValue]:[]);const display=computed(()=>selectedPaths.value.map(path=>all.value.find(entry=>pathKey(entry.path)===pathKey(path))?.labels.join(' / ')||path.join(' / ')).join('；'));
const matches=computed(()=>all.value.filter(entry=>(props.checkStrictly||!entry.node.children?.length)&&entry.labels.join(' / ').toLocaleLowerCase().includes(query.value.toLocaleLowerCase())));
const error=computed(()=>selectedPaths.value.some(path=>!all.value.some(entry=>pathKey(entry.path)===pathKey(path)&&!entry.disabled&&(props.checkStrictly||!entry.node.children?.length)))?t('cascader.invalid','已选路径无效或不可选择。'):'');
function entry(path:string[]){return all.value.find(item=>pathKey(item.path)===pathKey(path))!;}
function checked(item:MTreeEntry){const leaves=props.checkStrictly?[item]:descendants(item,all.value);return !!leaves.length&&leaves.every(leaf=>props.checkedPaths.some(path=>pathKey(path)===pathKey(leaf.path)));}
function partial(item:MTreeEntry){return !props.checkStrictly&&!checked(item)&&descendants(item,all.value).some(leaf=>props.checkedPaths.some(path=>pathKey(path)===pathKey(leaf.path)));}
function change(event:Event,item:MTreeEntry){const control=event.currentTarget as HTMLInputElement;choose(item);void nextTick(()=>{if(control.isConnected){control.checked=checked(item);control.indeterminate=partial(item);}});}
function searchKey(event:KeyboardEvent){if(event.isComposing)return;if(event.key==='ArrowDown'){event.preventDefault();(event.currentTarget as HTMLElement).parentElement?.querySelector<HTMLElement>('[data-ri-list] button:not(:disabled),[data-ri-list] input:not(:disabled)')?.focus();}else if(event.key==='Enter'){event.preventDefault();const available=matches.value.filter(item=>!item.disabled);if(query.value&&available.length===1)choose(available[0]!);}}
function choose(item:MTreeEntry){if(props.disabled||props.readonly||item.disabled)return;active.value=[...item.path];if(props.multiple){const targets=props.checkStrictly?[item]:descendants(item,all.value);const removing=checked(item);const keys=new Set(targets.map(target=>pathKey(target.path)));const next=props.checkedPaths.filter(path=>!keys.has(pathKey(path))).map(path=>[...path]);if(!removing)next.push(...targets.map(target=>target.path));emit('update:checkedPaths',next);}else if(props.checkStrictly||!item.node.children?.length){emit('update:modelValue',[...item.path]);open.value=false;}}
function clear(){if(props.disabled||props.readonly)return;if(props.multiple)emit('update:checkedPaths',[]);else emit('update:modelValue',[]);}
watch(()=>props.modelValue,value=>{active.value=[...value];},{deep:true});watch(()=>[props.disabled,props.readonly],()=>{if(props.disabled||props.readonly)open.value=false;});
</script>
<template><div class="ui-ri"><span class="ui-ri__label">{{label}}</span><div class="ui-ri__row"><MPopover v-model="open" :label="label" :trigger-label="label" :aria-description="display" :disabled="disabled||readonly"><template #trigger>{{display||t('cascader.placeholder','选择路径')}}</template><div class="ui-ri"><input v-if="filterable" v-model="query" class="ui-ri__control" @keydown="searchKey" :aria-label="t('search','搜索')+label" :placeholder="t('search','搜索')"><div v-if="query" class="ui-ri__list" data-ri-list><template v-for="item in matches" :key="pathKey(item.path)"><label v-if="multiple" class="ui-ri__row"><input type="checkbox" :checked="checked(item)" :indeterminate="partial(item)" @keydown="moveInList" :disabled="item.disabled" @change="change($event,item)">{{item.labels.join(' / ')}}</label><button v-else type="button" class="ui-ri__button" :disabled="item.disabled" @keydown="moveInList" @click="choose(item)">{{item.labels.join(' / ')}}</button></template><p v-if="!matches.length">{{t('empty','暂无数据')}}</p></div><div v-else class="ui-ri-cascader__columns"><section v-for="(column,index) in columns" :key="index" class="ui-ri__list" data-ri-list :aria-label="label+' '+(index+1)"><div v-for="node in column.nodes" :key="node.value" class="ui-ri__row"><label v-if="multiple"><input type="checkbox" :aria-label="[...column.prefix,node.value].join(' / ')+' '+node.label" :checked="checked(entry([...column.prefix,node.value]))" :indeterminate="partial(entry([...column.prefix,node.value]))" @keydown="moveInList" :disabled="entry([...column.prefix,node.value]).disabled" @change="change($event,entry([...column.prefix,node.value]))"></label><button type="button" class="ui-ri__button" :disabled="entry([...column.prefix,node.value]).disabled" :aria-pressed="active[index]===node.value" @keydown="moveInList" @click="multiple?active=[...column.prefix,node.value]:choose(entry([...column.prefix,node.value]))">{{node.label}} <span v-if="node.children?.length" aria-hidden="true">›</span></button></div></section></div></div></MPopover><button type="button" class="ui-ri__button" :disabled="disabled||readonly||!selectedPaths.length" @click="clear">{{t('clear','清空')}}</button></div><MValueBridge v-bind="props" :values="selectedPaths.map(path=>JSON.stringify(path))" :error="error"/></div></template>
<style scoped>.ui-ri-cascader__columns{display:flex;max-width:100%;overflow:auto;gap:12px}.ui-ri-cascader__columns>section{min-width:130px;flex:1}.ui-ri-cascader__columns .ui-ri__row{flex-wrap:nowrap}</style>
